static void init_features ( struct perf_session * session ) { int feat ; for ( feat = HEADER_FIRST_FEATURE ; feat < HEADER_LAST_FEATURE ; feat ++ ) { perf_header__set_feat ( & session -> header , feat ) ; } perf_header__clear_feat ( & session -> header , HEADER_BUILD_ID ) ; perf_header__clear_feat ( & session -> header , HEADER_TRACING_DATA ) ; perf_header__clear_feat ( & session -> header , HEADER_BRANCH_STACK ) ; } 